# Duration units, (singular, plural): hours, minutes, seconds
DURATION_UNITS = {
    "en": (("hour", "hours"), ("minute", "minutes"), ("second", "seconds")),
    "fr": (("heure", "heures"), ("minute", "minutes"), ("seconde", "secondes")),
    "es": (("hora", "horas"), ("minuto", "minutos"), ("segundo", "segundos")),
    "de": (("Stunde", "Stunden"), ("Minute", "Minuten"), ("Sekunde", "Sekunden")),
    "it": (("ora", "ore"), ("minuto", "minuti"), ("secondo", "secondi")),
    "pt": (("hora", "horas"), ("minuto", "minutos"), ("segundo", "segundos")),
}


def language() -> str:
    lang = config.load()["feedback"].get("language", "en")
    return lang if lang in LANGUAGES else "en"


def t(text_id: str, /, **values) -> str:
    """Text in the chosen language (English if the translation is missing)."""
    text = TEXTS[text_id].get(language()) or TEXTS[text_id]["en"]
    return text.format(**values) if values else text


def label(table: dict, key: str) -> str:
    """Label from a table (PAGES, NAV, ACCOUNT, PLAYER, ERRORS in safety.py): one value per language,
    in LABEL_ORDER order. A missing value falls back to English."""
    values = table.get(key, (key,))
    lang = language()
    i = LABEL_ORDER.index(lang) if lang in LABEL_ORDER else 0
    return values[i] if i < len(values) and values[i] else values[0]


# Talk key names: symbol, and left or right side in the chosen language
KEY_SYMBOLS = {"alt": "⌥", "cmd": "⌘", "ctrl": "⌃", "shift": "⇧"}
KEY_SIDES = {"en": ("left {k}", "right {k}"), "fr": ("{k} gauche", "{k} droite"), "es": ("{k} izquierda", "{k} derecha"),
             "de": ("{k} links", "{k} rechts"), "it": ("{k} sinistro", "{k} destro"), "pt": ("{k} esquerda", "{k} direita")}


def key_label(key: str) -> str:
    """Key name: "right ⌥", "⌥ droite" (French), "F13", "fn"."""
    if "_" not in key:
        return key.upper() if key.startswith("f") and key[1:].isdigit() else key
    name, side = key.split("_")
    left, right = KEY_SIDES.get(language(), KEY_SIDES["en"])
    return (right if side == "r" else left).format(k=KEY_SYMBOLS.get(name, name))


def decimal(value: float) -> str:
    """Number as text: "20.4" in English, "20,4" in the other languages."""
    text = f"{value:g}"
    return text if language() == "en" else text.replace(".", ",")


def clock_label(hour: int, minute: int) -> str:
    """Time said aloud: "14 h 30" (French), "2:30 PM" (English), "14:30" (others)."""
    lang = language()
    if lang == "fr":
        return f"{hour} h {minute:02d}" if minute else ("midi" if hour == 12 else "minuit" if hour == 0 else f"{hour} h")
    if lang == "en":
        return f"{(hour % 12) or 12}:{minute:02d} {'AM' if hour < 12 else 'PM'}" if minute else f"{(hour % 12) or 12} {'AM' if hour < 12 else 'PM'}"
    return f"{hour}:{minute:02d}"


def day_label(day, today) -> str:
    """Day label: "today", "tomorrow", or "Monday, September 28" (depending on the language)."""
    delta = (day - today).days
    if delta == 0:
        return t("day.today")
    if delta == 1:
        return t("day.tomorrow")
    lang = language()
    weekday = DAYS.get(lang, DAYS["en"])[day.weekday()]
    month = MONTHS.get(lang, MONTHS["en"])[day.month - 1]
    return t("day.format", weekday=weekday, day=day.day, month=month)


def when_label(moment, has_time: bool, now) -> str:
    """Moment label: "tomorrow at 9 AM", "Monday, September 28 at 2:30 PM", "tomorrow, all day"."""
    day = day_label(moment.date(), now.date())
    return t("when.at", day=day, time=clock_label(moment.hour, moment.minute)) if has_time else t("when.all_day", day=day)


def voice() -> str:
    return VOICES[language()]


AND = {"en": "and", "fr": "et", "es": "y", "de": "und", "it": "e", "pt": "e"}


def natural_duration(seconds: float) -> str:
    """Time left, said naturally: "56 seconds", "12 minutes and 30 seconds", "1 hour and 5 minutes"."""
    seconds = int(round(seconds))
    h, rest = divmod(seconds, 3600)
    m, s = divmod(rest, 60)
    hour, minute, second = DURATION_UNITS.get(language(), DURATION_UNITS["en"])
    if h:
        parts = [f"{h} {hour[h > 1]}"] + ([f"{m} {minute[m > 1]}"] if m else [])
    elif m:
        parts = [f"{m} {minute[m > 1]}"] + ([f"{s} {second[s > 1]}"] if s else [])
    else:
        parts = [f"{s} {second[s > 1]}"]
    return f" {AND.get(language(), 'and')} ".join(parts)


def spoken_duration(seconds: float, precise: bool = False) -> str:
    """Duration: "1 hour 20", "4 minutes"; precise: "4 minutes 30" under 10 minutes (timers)."""
    seconds = int(round(seconds))
    h, rest = divmod(seconds, 3600)
    m, s = divmod(rest, 60)
    hour, minute, second = DURATION_UNITS.get(language(), DURATION_UNITS["en"])
    if h:
        return f"{h} {hour[h > 1]}" + (f" {m}" if m else "")
    if m:
        return f"{m} {minute[m > 1]}" + (f" {s}" if precise and s and m < 10 else "")
    return f"{s} {second[s > 1]}"
